head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07301";
scwin.panel_debug = null;
scwin.dts_Grid = null;
scwin.pMarket = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        fn_SetCode();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_SetCode — as-is 공통(폼 전역 의존) — 반입 보류
        await scwin.tx_script_dts_Grid();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07301.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pMarket =$c.session.getUserInfo("market"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07301' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.panel_debug = $c.util.getComponent('panel_debug');
        scwin.dts_Grid = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid')) : $c.util.getComponent('dts_Grid');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07301.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description btn_Save 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Save_onclick = async function () {
    try {
        await scwin.sbm_trs_Save();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07301.btn_Save_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07301.btn_Close_onclick' }); }
};

/**
 * @method
 * @name trs_Save_onfail
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onfail = async function () {
    try {
        await $c.win.alert("저장에 실패하였습니다.");
        $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07301.trs_Save_onfail" });
    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
        await $c.win.alert("저장하였습니다.");
        scwin.parentRefresh();
        $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07301.trs_Save_onsuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_Grid
 * @description script dts Grid 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_Grid = async function () {
    $c.util.getComponent("dma_scriptDts_GridReq").set("SCREN_ID", "ULDSTF07301.gfm");
    $c.util.getComponent("dma_scriptDts_GridReq").set("inputMessageId", "PREPARE_CORP_STATUS");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, BZ_PROCS_NO", unresolved: "query_param:SCREN_PROCES_TP_CD,BZ_PROCS_NO" };
    const sbmOptions = {
        id: "tx_script_dts_Grid",
        method: "post",
        action: "/konex/Prelisting.do",
        ref: "dma_scriptDts_GridReq",
        target: "dts_Grid=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Grid_onloaderror'] === 'function') ? scwin['dts_Grid_onloaderror'] : (typeof scwin['dts_Grid_onfail'] === 'function') ? scwin['dts_Grid_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Grid_onloadcompleted'] === 'function') ? scwin['dts_Grid_onloadcompleted'] : ((typeof scwin['dts_Grid_onsuccess'] === 'function') ? scwin['dts_Grid_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Grid'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07301.tx_script_dts_Grid" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name sbm_trs_Save
 * @description trs Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/konex/Prelisting.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07301.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function () {
    scwin.panel_debug.hide();
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function () {
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
